<script setup>
import { vCanAction } from '../../../services/permission-directives.js'
import { canArea, canAction } from '../../../services/access.js'
import { getStoredUser } from '../../../services/tokens.js'
import { onMounted, ref } from 'vue'
import LibraryReferencePicker from '../components/LibraryReferencePicker.vue'
import { api, messageOf } from '../services.js'
const may = action => canAction(getStoredUser(), 'web_integrations', action)
const payments = ref([]), profiles = ref([]), groups = ref([]), assets = ref([]), models = ref([]), imageModels = ref([]), credentialNames = ref([]), toast = ref(''), busy = ref(false)
const payment = ref(null), profile = ref(null), apiKey = ref('')
const defaultWebhook = `${location.origin}/comunicacao/api/whatsapp-web/integrations/infinitepay/webhook`
const money = cents => (Number(cents || 0) / 100).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })
function cents(value) { const clean = String(value || '').replace(/[^\d,.]/g, ''); return Math.round(Number(clean.includes(',') ? clean.replace(/\./g, '').replace(',', '.') : clean) * 100) }
function show(value) { toast.value = value; setTimeout(() => { if (toast.value === value) toast.value = '' }, 4000) }
async function refreshModels() {
  if (!may('configure')) return
  busy.value=true
  try { const value=await api.get('/integrations/openai/models',{params:{credentialName:profile.value?.credentialName || 'OPENAI_API_KEY'}});models.value=[...new Set([...value.data.models.map(item=>item.id),...profiles.value.flatMap(item=>[item.model,item.visionModel])])];show('Modelos atualizados com a credencial selecionada.') } catch(error){show(messageOf(error))}finally{busy.value=false}
}
async function load() {
  busy.value = true
  try {
    const [p, a, g, files, credentials] = await Promise.all([api.get('/integrations/infinitepay/configs'), api.get('/integrations/openai/profiles'), api.get('/integrations/contact-groups'), canArea(getStoredUser(), 'web_files') ? api.get('/assets', { params: { limit: 100 } }) : Promise.resolve({ data: {items: []} }), canArea(getStoredUser(), 'web_settings') ? api.get('/settings/credentials') : Promise.resolve({ data: {items: []} })])
    payments.value = p.data.items; profiles.value = a.data.items; models.value = [...new Set([...a.data.models,...a.data.items.flatMap(item=>[item.model,item.visionModel])].filter(Boolean))]; imageModels.value = a.data.imageModels; groups.value = g.data.items; assets.value = files.data.items
    credentialNames.value = [...new Set((credentials.data.items || []).map(item => item.name).filter(Boolean))].sort()
  } catch (error) { show(messageOf(error)) } finally { busy.value = false }
}
function editPayment(item = {}) { payment.value = { key: item.key || '', title: item.title || '', handle: item.handle || '', product: item.product || '', originalPrice: String((item.originalPriceCents ?? 10000) / 100).replace('.', ','), price: String((item.priceCents ?? 10000) / 100).replace('.', ','), webhookUrl: item.webhookUrl || defaultWebhook, paidMessage: item.paidMessage || '✅ Pagamento de {{valor}} aprovado. Comprovante: {{comprovante}}', declinedMessage: item.declinedMessage || 'Pagamento não confirmado. Tente novamente: {{link_pagamento}}', teamMessage: item.teamMessage || '', recipientsText: (item.recipients || []).join('\n'), contactGroupIds: item.contactGroupIds || [], enabled: item.enabled !== false } }
async function savePayment() { if (!may('configure')) return; busy.value = true; try { const item = payment.value; await api.put(`/integrations/infinitepay/configs/${encodeURIComponent(item.key)}`, { ...item, priceCents: cents(item.price), originalPriceCents: cents(item.originalPrice), recipients: item.recipientsText.split(/[\n,;]+/).map(s => s.trim()).filter(Boolean) }); payment.value = null; await load(); show('Configuração de pagamento salva.') } catch (error) { show(messageOf(error)) } finally { busy.value = false } }
function editProfile(item = {}) { profile.value = { key: item.key || '', title: item.title || '', credentialName: item.credentialName || '', model: item.model || 'gpt-5.5', visionModel: item.visionModel || 'gpt-5.5', imageModel: item.imageModel || 'gpt-image-2.5-sunburst', temperature: item.temperature ?? 0.7, timeoutMinutes: item.timeoutMinutes ?? 0, idleResetMessage: item.idleResetMessage || "", resetCommand: item.resetCommand || '/desligar', contextText: (item.context || []).filter(c => c.type === 'text').map(c => c.text).join('\n\n'), assetIds: (item.context || []).filter(c => c.type === 'asset').map(c => c.assetId), generateImages: item.generateImages !== false, generateDocuments: item.generateDocuments !== false } }
async function saveProfile() { if (!may('edit')) return; busy.value = true; try { const item = profile.value; await api.put(`/integrations/openai/profiles/${encodeURIComponent(item.key)}`, { ...item, context: [...(item.contextText.trim() ? [{ type: 'text', text: item.contextText.trim() }] : []), ...item.assetIds.map(assetId => ({ type: 'asset', assetId }))] }); profile.value = null; await load(); show('Perfil OpenAI salvo.') } catch (error) { show(messageOf(error)) } finally { busy.value = false } }
async function saveKey() { if (!canAction(getStoredUser(), 'web_settings', 'credentials')) return; busy.value = true; try { const found = (await api.get('/settings/credentials')).data.items.find(c => c.name === 'OPENAI_API_KEY'); if (found) await api.put(`/settings/credentials/${found._id}`, { name: 'OPENAI_API_KEY', description: 'OpenAI BotBuilder', value: apiKey.value }); else await api.post('/settings/credentials', { name: 'OPENAI_API_KEY', description: 'OpenAI BotBuilder', value: apiKey.value }); apiKey.value = ''; await load(); show('Chave OpenAI salva e criptografada.') } catch (error) { show(messageOf(error)) } finally { busy.value = false } }
onMounted(load)
</script>
<template>
  <section><div class="page-head"><div><span class="eyebrow">Conexões do fluxo</span><h1>Integrações</h1><p>Configure pagamentos e IA para os cards do BotBuilder. Gerencie grupos na aba Contatos.</p></div><button class="btn secondary" @click="load">Atualizar</button></div>
    <div class="integration-grid"><article class="card panel"><div class="panel-head"><div><span class="eyebrow">CHECKOUT</span><h2>InfinitePay</h2></div><button v-can-action="'web_integrations.configure'" class="btn" @click="editPayment()">Nova configuração</button></div><p>Crie links de pagamento pelo fluxograma. Valores em reais são enviados em centavos para a API.</p><button v-for="item in payments" :key="item.key" class="list-item" @click="editPayment(item)"><strong>{{ item.title }}</strong><span>${{ item.handle }} · {{ money(item.priceCents) }}</span></button><small>A InfinitePay documenta webhook de aprovação. Registre recusa após conferir no painel do provedor.</small></article>
      <article class="card panel"><div class="panel-head"><div><span class="eyebrow">ASSISTENTE</span><h2>OpenAI</h2></div><button v-can-action="'web_integrations.edit'" class="btn" @click="editProfile()">Novo perfil</button></div><p>Escolha modelos de conversa, interpretação de imagem e geração. Cada chat mantém seu próprio contexto.</p><div v-can-action="'web_settings.credentials'" class="field"><label>Chave da API OpenAI</label><input v-model="apiKey" type="password" autocomplete="new-password" placeholder="sk-..."><small>A chave é criptografada no servidor e não volta para o navegador.</small></div><button v-can-action="'web_settings.credentials'" class="btn secondary" :disabled="!apiKey || busy" @click="saveKey">Salvar chave</button><button v-for="item in profiles" :key="item.key" class="list-item" @click="editProfile(item)"><strong>{{ item.title }}</strong><span>{{ item.model }} · visão {{ item.visionModel }}</span></button></article>
      </div>
    <div v-if="payment" class="modal-backdrop"><form class="card modal" @submit.prevent="savePayment"><div class="panel-head"><h2>InfinitePay</h2><button type="button" class="icon-button" @click="payment = null">×</button></div><div class="fields"><div class="field"><label>Identificador</label><input v-model="payment.key" :readonly="payments.some(p => p.key === payment.key)" required></div><div class="field"><label>Título</label><input v-model="payment.title" required></div><div class="field"><label>InfiniteTag / login</label><input v-model="payment.handle" required></div><div class="field"><label>Produto</label><input v-model="payment.product" required></div><div class="field"><label>Preço original (R$)</label><input v-model="payment.originalPrice" required></div><div class="field"><label>Preço de venda (R$)</label><input v-model="payment.price" required></div><div class="field wide"><label>Webhook HTTPS</label><input v-model="payment.webhookUrl" required></div><div class="field wide"><label>Mensagem aprovada</label><textarea v-model="payment.paidMessage"></textarea></div><div class="field wide"><label>Mensagem recusada</label><textarea v-model="payment.declinedMessage"></textarea></div><div class="field wide"><label>Aviso para equipe</label><textarea v-model="payment.teamMessage"></textarea></div><div class="field"><label>Destinatários, um por linha</label><textarea v-model="payment.recipientsText"></textarea></div><div class="field"><label>Grupos de contatos</label><select v-model="payment.contactGroupIds" multiple><option v-for="item in groups" :key="item._id" :value="item._id">{{ item.name }}</option></select></div></div><label class="toggle"><input v-model="payment.enabled" type="checkbox"> Ativar esta configuração</label><p class="help" v-pre>Variáveis: {{nome_contato}}, {{num_contato}}, {{valor}}, {{pedido}}, {{comprovante}}, {{link_pagamento}}.</p><button v-can-action="'web_integrations.configure'" class="btn" :disabled="busy">Salvar configuração</button></form></div>
    <div v-if="profile" class="modal-backdrop" role="presentation"><form class="card modal openai-profile-modal" role="dialog" aria-modal="true" aria-label="Perfil OpenAI" @submit.prevent="saveProfile"><div class="panel-head"><h2>Perfil OpenAI</h2><button type="button" class="icon-button" @click="profile = null">×</button></div><div class="fields"><div class="field"><label>Identificador</label><input v-model="profile.key" :readonly="profiles.some(p => p.key === profile.key)" required></div><div class="field"><label>Título</label><input v-model="profile.title" required></div>
      <div class="field wide">
        <label for="profile-credential">Credencial da API OpenAI</label>
        <select id="profile-credential" v-model="profile.credentialName" aria-describedby="profile-credential-help">
          <option value="">Padrão (OPENAI_API_KEY)</option>
          <option v-if="profile.credentialName && !credentialNames.includes(profile.credentialName)" :value="profile.credentialName">{{ profile.credentialName }} (não encontrada)</option>
          <option v-for="name in credentialNames" :key="name" :value="name">{{ name }}</option>
        </select>
        <small id="profile-credential-help">Selecione uma credencial salva em Configurações. Apenas o nome é exibido; o valor permanece protegido.</small>
      </div>
      <div class="field wide"><button type="button" class="btn secondary" :disabled="busy||!may('configure')" @click="refreshModels">Atualizar modelos disponíveis</button><small>Consulta os modelos atuais da conta OpenAI selecionada, preservando os perfis salvos.</small></div><div class="field"><label>Modelo de conversa</label><select v-model="profile.model"><option v-for="model in models" :key="model">{{ model }}</option></select></div><div class="field"><label>Interpretação de imagem</label><select v-model="profile.visionModel"><option v-for="model in models" :key="model">{{ model }}</option></select></div><div class="field"><label>Geração/edição de imagem</label><select v-model="profile.imageModel"><option v-for="model in imageModels" :key="model">{{ model }}</option></select></div><div v-if="!/^gpt-[5-9]/.test(profile.model)" class="field"><label>Temperatura</label><input v-model.number="profile.temperature" type="number" min="0" max="2" step="0.1"></div><div v-if="/^gpt-[5-9]/.test(profile.model)" class="field"><label>Raciocínio</label><small>Controle automático pelo modelo; temperatura não é enviada. O contexto continua configurável abaixo.</small></div><div class="field"><label>Comando para limpar contexto</label><input v-model="profile.resetCommand"></div><div class="field"><label>Inatividade para resetar (min)</label><input v-model.number="profile.timeoutMinutes" type="number" min="0" max="1440"></div><div class="field wide"><small>0 mantém a memória desta conversa sem reinício por inatividade. O histórico enviado depende da opção do card.</small><label>Mensagem opcional após reinício automático</label><textarea v-model="profile.idleResetMessage" maxlength="3000" placeholder="Deixe vazio para reiniciar em silêncio"></textarea></div><div class="field wide"><label>Instruções e contexto em texto</label><textarea v-model="profile.contextText"></textarea></div><div class="field wide"><LibraryReferencePicker v-model="profile.assetIds" :assets="assets" /></div></div><label class="toggle"><input v-model="profile.generateImages" type="checkbox"> Permitir criar/editar imagens</label><label class="toggle"><input v-model="profile.generateDocuments" type="checkbox"> Permitir criar/editar documentos</label><div class="profile-form-actions"><button type="button" class="btn secondary" @click="profile = null">Cancelar</button><button v-can-action="'web_integrations.edit'" class="btn" :disabled="busy">Salvar perfil</button></div></form></div>
    <div v-if="toast" class="toast">{{ toast }}</div>
  </section>
</template>
<style scoped>
.integration-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.panel{padding:22px;display:grid;align-content:start;gap:12px}.panel-head{display:flex;align-items:center;justify-content:space-between;gap:12px}.panel h2{margin:.2rem 0;font:800 1.2rem Inter,'Segoe UI',sans-serif}.panel p,.panel small,.help{color:var(--muted);font-size:.8rem;line-height:1.5}.list-item{display:grid;width:100%;gap:4px;padding:12px;border:1px solid var(--line);border-radius:11px;text-align:left;background:#f7fbf9}.list-item span{color:var(--muted);font-size:.75rem}.modal-backdrop{position:fixed;inset:0;z-index:90;display:grid;place-items:center;padding:15px;background:#08251e9c}.modal{width:min(800px,100%);max-height:90dvh;overflow:auto;padding:24px;color:var(--ink);background:#fff}.modal .field label{font-size:.85rem;color:#304b43}.modal .field input,.modal .field textarea,.modal .field select{color:#10231f;background:#fff;font-size:.93rem}.modal .field input::placeholder,.modal .field textarea::placeholder{color:#657b73}.fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin:16px 0}.wide{grid-column:1/-1}.modal>.btn{margin-top:12px}.field select[multiple]{min-height:100px}@media(max-width:750px){.integration-grid,.fields{grid-template-columns:1fr}.wide{grid-column:auto}.panel-head{flex-wrap:wrap}.modal{padding:18px}}
.openai-profile-modal{min-width:0;scrollbar-gutter:stable;overscroll-behavior:contain}.openai-profile-modal>.panel-head{position:sticky;top:-24px;z-index:3;background:color-mix(in srgb,var(--brand,#35bca4) 6%,white);padding:14px 0;margin-top:-14px;border-bottom:1px solid var(--line);flex-wrap:nowrap}.modal>.panel-head h2{font-size:20px;line-height:1.3;font-weight:750;margin:0;min-width:0}.modal>.panel-head>.icon-button{flex:none}.openai-profile-modal .field{min-width:0}.profile-form-actions{display:flex;justify-content:flex-end;gap:8px;position:sticky;bottom:-24px;z-index:2;padding:14px 0;margin-top:12px;background:white;border-top:1px solid var(--line)}@media(max-width:750px){.openai-profile-modal>.panel-head{top:-18px}.profile-form-actions{bottom:-18px}}
</style>
